type titleError string

func (e titleError) Error() string { return string(e) }

func unique[T comparable](values []T) []T {
    seen := make(map[T]bool)
    result := []T{}
    for _, value := range values {
        if !seen[value] {
            seen[value] = true
            result = append(result, value)
        }
    }
    return result
}

func main() {
